#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sched.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <dirent.h>
#include <errno.h>

int main() {
    // Try to open the initial PID namespace 
    // The initial PID namespace inode should be findable
    // We need to find any PID that's in the HOST/initial PID namespace

    // Check all /proc/*/ns/pid entries we can see to find the initial one
    DIR *dp = opendir("/proc");
    struct dirent *ep;

    printf("Scanning /proc for PIDs...\n");

    if (!dp) {
        perror("opendir /proc");
        return 1;
    }

    while ((ep = readdir(dp))) {
        if (ep->d_type != DT_DIR) continue;

        // Check if numeric
        char *endp;
        long pid = strtol(ep->d_name, &endp, 10);
        if (*endp != '\0') continue;

        char ns_path[256];
        snprintf(ns_path, sizeof(ns_path), "/proc/%ld/ns/pid", pid);

        struct stat st;
        if (stat(ns_path, &st) == 0) {
            printf("PID %ld: pid ns inode = %lu\n", pid, st.st_ino);
        }
    }

    closedir(dp);

    return 0;
}
